@startuml

class CarPark {}

class Barrier {
  + raise()
}

class CardReader {
  + verifyCardNumber()
}

class Signal {}

class Sign {
  + displayFull()
  + switchOff()
}

class Card {}

class StaffCard extends Card {
  + name : string
  + department : string
  + staffNumber : int
}

class GuestCard extends Card {
  + number : int
  + currentDate : date
}

class Employee {}

class Driver {}

CarPark "1" *-- "*" Barrier
CarPark "1" *-- "*" CardReader
CarPark "1" -- "1" Sign
CardReader ..> Signal : triggers
Barrier ..> Signal : triggered by
Driver "1" -- "1" Card : uses
Employee "1" -- "1" StaffCard : wears

@enduml

